#include <stdio.h>
#include <stdlib.h>

#define MAX_N 200000
#define MAX_Q 200000

typedef struct {
    int score;
    int is_leader;
} Student;

Student students[MAX_N];
int n, q;
int leader_scores[MAX_N];
int leader_count;

int cmp(const void *a, const void *b) {
    return *(int*)a - *(int*)b;
}

int count_unable(int r) {
    // For each leader, count how many non-leaders can join
    // A non-leader with score s can join a leader with score L if L <= s and s - L <= r
    // So for each non-leader, find the highest leader with score <= s, check if s - L <= r
    // If no such leader or s - L > r, the non-leader cannot join any group.

    int unable = 0;
    if (leader_count == 0) {
        // No leaders, all non-leaders cannot participate
        for (int i = 0; i < n; i++) {
            if (!students[i].is_leader) unable++;
        }
        return unable;
    }

    // Sort leader scores for binary search
    int sorted_leaders[leader_count];
    for (int i = 0; i < leader_count; i++) {
        sorted_leaders[i] = leader_scores[i];
    }
    qsort(sorted_leaders, leader_count, sizeof(int), cmp);

    for (int i = 0; i < n; i++) {
        if (students[i].is_leader) continue;
        int s = students[i].score;

        // Binary search for the largest leader score <= s
        int lo = 0, hi = leader_count - 1;
        int best = -1;
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            if (sorted_leaders[mid] <= s) {
                best = mid;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }

        if (best == -1 || s - sorted_leaders[best] > r) {
            unable++;
        }
    }
    return unable;
}

int main() {
    scanf("%d %d", &n, &q);
    for (int i = 0; i < n; i++) {
        scanf("%d", &students[i].score);
        students[i].is_leader = 0;
    }
    leader_count = 0;

    for (int i = 0; i < q; i++) {
        int type;
        scanf("%d", &type);
        if (type == 1) {
            int a;
            scanf("%d", &a);
            a--; // 0-index
            if (!students[a].is_leader) {
                students[a].is_leader = 1;
                leader_scores[leader_count++] = students[a].score;
            }
        } else if (type == 2) {
            int a;
            scanf("%d", &a);
            a--;
            if (students[a].is_leader) {
                students[a].is_leader = 0;
                // Remove from leader_scores array (we'll rebuild later)
                int found = 0;
                for (int j = 0; j < leader_count; j++) {
                    if (leader_scores[j] == students[a].score && !found) {
                        found = 1;
                        // Shift left
                        for (int k = j; k < leader_count - 1; k++) {
                            leader_scores[k] = leader_scores[k+1];
                        }
                        leader_count--;
                        break;
                    }
                }
            }
        } else if (type == 3) {
            int x;
            scanf("%d", &x);

            // Binary search for minimal r
            int lo = 0, hi = 1000000000;
            int ans = -1;
            while (lo <= hi) {
                int mid = (lo + hi) / 2;
                if (count_unable(mid) <= x) {
                    ans = mid;
                    hi = mid - 1;
                } else {
                    lo = mid + 1;
                }
            }
            printf("%d\n", ans);
        }
    }

    return 0;
}

