void add_leader(int v) {
    int pos = 0, lo = 0, hi = nleaders;
    while (lo < hi) { int mid=(lo+hi)/2; if(leaders[mid]<v) lo=mid+1; else hi=mid; }
    memmove(leaders+lo+1, leaders+lo, (nleaders-lo)*sizeof(int));
