void rem_leader(int v) {
    int lo=0,hi=nleaders;
    while(lo<hi){int mid=(lo+hi)/2;if(leaders[mid]<v)lo=mid+1;else hi=mid;}
    memmove(leaders+lo, leaders+lo+1, (nleaders-lo-1)*sizeof(int));
    nleaders--;
}

int count_unmatched(int r, int *nonleaders, int nn) {
    int cnt = 0;
    for (int i = 0; i < nn; i++) {
        int s = nonleaders[i];
        // find leader in [s, s+r]
        int lo=0,hi=nleaders;
        while(lo<hi){int mid=(lo+hi)/2;if(leaders[mid]<s)lo=mid+1;else hi=mid;}
        if (lo < nleaders && leaders[lo] <= s+r) continue;
        cnt++;
    }
    return cnt;
}

