typedef long long ll;

static int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll*)a;
    ll y = *(const ll*)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main(void) {
    int N, Q;
    if (scanf("%d %d", &N, &Q) != 2) return 0;

    ll *score = (ll*)malloc(sizeof(ll) * N);
    for (int i = 0; i < N; i++) scanf("%lld", &score[i]);

    ll *sorted = (ll*)malloc(sizeof(ll) * N);
    for (int i = 0; i < N; i++) sorted[i] = score[i];
    qsort(sorted, N, sizeof(ll), cmp_ll);

    /* pos[i] = rank of score[i] in sorted order (scores are unique) */
    int *pos = (int*)malloc(sizeof(int) * N);
    for (int i = 0; i < N; i++) {
        int l = 0, r = N - 1;
        while (l <= r) {
            int m = (l + r) >> 1;
            if (sorted[m] == score[i]) {
                pos[i] = m;
                break;
            } else if (sorted[m] < score[i]) {
                l = m + 1;
            } else {
                r = m - 1;
            }
        }
    }

    char *isLeader = (char*)calloc(N, sizeof(char));
    int *leaderPos = (int*)malloc(sizeof(int) * N);
    int leaderCnt = 0;

    for (int qi = 0; qi < Q; qi++) {
        int t;
        scanf("%d", &t);

        if (t == 1) {
            int k;
            scanf("%d", &k);
            k--;
            if (!isLeader[k]) {
                isLeader[k] = 1;
                leaderPos[leaderCnt++] = pos[k];
            }
        } else if (t == 2) {
            int k;
            scanf("%d", &k);
            k--;
            if (isLeader[k]) {
                isLeader[k] = 0;
                int p = pos[k];
                for (int i = 0; i < leaderCnt; i++) {
                    if (leaderPos[i] == p) {
                        leaderPos[i] = leaderPos[leaderCnt - 1];
                        leaderCnt--;
                        break;
                    }
                }
            }
        } else {
            int x;
            scanf("%d", &x);

            if (leaderCnt == 0) {
                printf("-1\n");
                continue;
            }

            qsort(leaderPos, leaderCnt, sizeof(int), cmp_ll);

            int need = N - x;
            if (need <= 0) {
                printf("0\n");
                continue;
            }

            int best = 0;
            for (int i = 0; i < leaderCnt; i++) {
                int j = i + need - 1;
                if (j >= N) break;
                ll diff = sorted[j] - sorted[leaderPos[i]];
                if (i == 0 || diff < best || best == 0 && i == 0) best = (int)diff;
            }

            /* Better directly compute minimum over each leader:
               students covered by leader at rank p are a suffix [p .. upper]
               to cover at least need students with one of the leaders as minimum feasible leader,
               choose j = p + need - 1.
            */
            ll ans = -1;
            for (int i = 0; i < leaderCnt; i++) {
                int p = leaderPos[i];
                int j = p + need - 1;
                if (j < N) {
                    ll diff = sorted[j] - sorted[p];
                    if (ans == -1 || diff < ans) ans = diff;
                }
            }
            printf("%lld\n", ans);
        }
    }

    free(score);
    free(sorted);
    free(pos);
    free(isLeader);
    free(leaderPos);
    return 0;
}

