public class Main {
    static int N;
    static int[] scores;
    static TreeSet<Integer> leaderSet; // stores indices of leaders
    static int[] parent; // union-find parent for grouping by score intervals

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        N = Integer.parseInt(st.nextToken());
        int Q = Integer.parseInt(st.nextToken());

        scores = new int[N];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < N; i++) {
            scores[i] = Integer.parseInt(st.nextToken());
        }

        leaderSet = new TreeSet<>();
        parent = new int[N];
        for (int i = 0; i < N; i++) parent[i] = i;

        StringBuilder sb = new StringBuilder();
        for (int q = 0; q < Q; q++) {
            st = new StringTokenizer(br.readLine());
            int type = Integer.parseInt(st.nextToken());
            if (type == 1) {
                // add leader
                int idx = Integer.parseInt(st.nextToken()) - 1;
                leaderSet.add(idx);
                // try to merge with adjacent leaders
                Integer lower = leaderSet.lower(idx);
                if (lower != null && canMerge(lower, idx)) {
                    union(lower, idx);
                }
                Integer higher = leaderSet.higher(idx);
                if (higher != null && canMerge(idx, higher)) {
                    union(idx, higher);
                }
            } else if (type == 2) {
                // remove leader
                int idx = Integer.parseInt(st.nextToken()) - 1;
                leaderSet.remove(idx);
                // After removal, we don't split union-find; it's fine to keep merged.
                // The leader set is used for counting groups.
            } else {
                // query: find minimal r such that at most x students cannot participate
                int x = Integer.parseInt(st.nextToken());
                sb.append(findMinR(x)).append("\n");
            }
        }
        System.out.print(sb);
    }

    static boolean canMerge(int i, int j) {
        // two leaders can merge if their score difference <= current r? Not used.
        // For union by score adjacency, we always merge adjacent leaders.
        return true;
    }

    static int find(int a) {
        while (parent[a] != a) {
            parent[a] = parent[parent[a]];
            a = parent[a];
        }
        return a;
    }

    static void union(int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra != rb) {
            parent[ra] = rb;
        }
    }

    static int findMinR(int x) {
        // If no leaders, no one can participate -> all N cannot participate.
        if (leaderSet.isEmpty()) return 0; // Actually need infinite? But problem expects finite.
        // Collect groups: each component has a leader with min and max score.
        // But we only need leaders sorted by score.
        List<Integer> leaders = new ArrayList<>(leaderSet);
        Collections.sort(leaders, Comparator.comparingInt(i -> scores[i]));

        // Binary search on r
        int lo = 0, hi = 2000000000; // score range up to 1e9, but we can bound by max diff
        int ans = hi;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            if (canCover(x, leaders, mid)) {
                ans = mid;
                hi = mid - 1;
            } else {
                lo = mid + 1;
            }
        }
        return ans;
    }

    static boolean canCover(int x, List<Integer> leaders, int r) {
        // Count students that can be covered by some leader within radius r
        // We have leaders sorted by score.
        // For each leader, the students it can cover are those with score in [scores[leader]-r, scores[leader]+r]
        // But students cannot join leaders with higher score than their own.
        // So a student with score s can join leader with score L only if L <= s and s - L <= r.
        // Equivalently, for a leader L, the students it can cover have score in [L, L+r].
        // So we need to find how many students have score >= some leader's score and <= that leader's score + r
        // and not covered by any leader with lower score (since lower score leaders can also cover them if within r).
        // Actually a student can join any leader that satisfies L <= s <= L+r.
        // So we can process leaders in increasing order and cover intervals.
        // The union of intervals [L, L+r] for all leaders gives the set of students that can participate.
        // We need to compute the total number of students whose scores fall in this union.
        // Then check if N - covered <= x.

        // Since N up to? Not given, but we can use prefix sums if scores are discrete.
        // But scores can be up to 1e9, N up to maybe 200k? We'll compress.
        // Simpler: sort all scores, then for each leader, find range of indices with score in [L, L+r]
        // using binary search, and mark covered. But we need union of intervals.
        // We can use two-pointer sweep over sorted scores and leaders.

        // Let's sort scores once globally.
        // We'll use static sortedScores array.
        // But we need to call this many times, so precompute sorted scores.
        // We'll store globally.
        // For now, implement inside.

        int[] sortedScores = getSortedScores();
        int n = N;
        int covered = 0;
        int leaderIdx = 0;
        int m = leaders.size();
        int i = 0; // index in sortedScores
        while (i < n && leaderIdx < m) {
            int L = scores[leaders.get(leaderIdx)];
            int right = L + r;
            // skip scores less than L (since student score must be >= L)
            while (i < n && sortedScores[i] < L) i++;
            // count scores in [L, right]
            int start = i;
            while (i < n && sortedScores[i] <= right) i++;
            covered += (i - start);
            leaderIdx++;
        }
        return (n - covered) <= x;
    }

    static int[] sortedScoresCache = null;
    static int[] getSortedScores() {
        if (sortedScoresCache == null) {
            sortedScoresCache = scores.clone();
            Arrays.sort(sortedScoresCache);
        }
        return sortedScoresCache;
    }
}

import java.io.*;
import java.util.*;

/*
 * Study Group Simulation
 *
 * We have N students with scores.
 * Some students are leaders. A non-leader student with score s can join a leader
 * with score L only if:
 *   1) L <= s
 *   2) s - L <= r
 * i.e. there exists a leader score in [s-r, s].
 *
 * For each query:
 *  - add/remove a leader by student index
 *  - ask minimum r such that at most x students cannot participate in any group
 *
 * Key observation for a fixed set of leaders:
 * A student with score s is coverable iff predecessor leader score p <= s exists and s-p <= r.
 * Let gap(s) = s - predecessorLeaderScore(s), or INF if no predecessor leader.
 * Then student is uncovered iff gap(s) > r.
 *
 * So for a query "minimum r so that uncovered <= x", we need the (cnt-x)-th smallest
 * value among finite gaps of all students, where cnt = number of students that have some
 * predecessor leader. Students before the first leader are always impossible (INF), thus
 * they always contribute to uncovered.
 *
 * More precisely:
 * Let impossible = number of students with no leader score <= their score.
 * Need uncovered <= x.
 * If impossible > x => impossible for any finite r, but in this problem we output minimum r;
 * because if there is at least one leader, eventually all with predecessor are covered, but
 * impossible remain. So if impossible > x, answer is -1.
 * Else among finite gaps, we need at least need = finiteCount - (x - impossible) covered,
 * meaning r must be at least the need-th smallest finite gap (1-indexed), or 0 if need<=0.
 *
 * Data structure:
 * Scores compressed by distinct values.
 * For each score value v:
 *   totalCnt[v] = number of students with this exact score
 *   leaderCnt[v] = number of leaders with this score
 *
 * Finite gap values arise interval-wise:
 * If a score value a has leaders, then for all score values t in [a, nextLeaderScore-1 among existing score values],
 * predecessor leader is a, so all students with score score[t] contribute gap = score[t]-score[a].
 *
 * We maintain all current leaders in a TreeSet of score indices.
 * Also maintain a Fenwick tree over possible gap values (actual score differences among existing score values),
 * storing multiplicities of students with finite gap equal to that value.
 * Additionally maintain finiteTotal = total number of students with finite gap.
 *
 * When a score index becomes leader-active from 0 to 1, it splits one interval into two.
 * When it becomes inactive from 1 to 0, it merges two intervals.
 * We can update the gap multiset by iterating score indices in affected ranges and adjusting counts.
 *
 * Complexity:
 * Let M be number of distinct scores.
 * Each leader toggle may touch O(length of neighboring interval) score values.
 * This is acceptable only if constraints are moderate. Since statement omitted here, we provide
 * a robust and simpler implementation. Query asks are O(log V).
 */

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static class Fenwick {
        long[] bit;
        int n;
        Fenwick(int n) {
            this.n = n;
            bit = new long[n + 2];
        }
        void add(int idx, long delta) {
            idx++;
            while (idx <= n + 1) {
                bit[idx] += delta;
                idx += idx & -idx;
            }
        }
        long sumPrefix(int idx) {
            idx++;
            long res = 0;
            while (idx > 0) {
                res += bit[idx];
                idx -= idx & -idx;
            }
            return res;
        }
        // smallest idx such that prefix sum >= k, assuming k>=1 and total>=k
        int lowerBound(long k) {
            int idx = 0;
            int bitMask = Integer.highestOneBit(n + 1);
            long cur = 0;
            for (int d = bitMask; d != 0; d >>= 1) {
                int next = idx + d;
                if (next <= n + 1 && cur + bit[next] < k) {
                    idx = next;
                    cur += bit[next];
                }
            }
            return idx; // 0-based fenwick internal predecessor, actual index = idx
        }
    }

    static int N, Q;
    static int[] score;
    static int[] studentScoreIdx;
    static int[] uniqScores;
    static int M;

    static int[] totalCnt;
    static int[] leaderCntByScore;
    static boolean[] isLeaderStudent;
    static TreeSet<Integer> activeLeaderScores = new TreeSet<>();

    static Fenwick fw;
    static long finiteTotal = 0;

    static int[] diffValues; // compressed possible gap values
    static HashMap<Integer, Integer> diffToIdx = new HashMap<>();

    static void addGapCount(int gap, long cnt) {
        if (cnt == 0) return;
        int idx = diffToIdx.get(gap);
        fw.add(idx, cnt);
        finiteTotal += cnt;
    }

    static void rangeAssignLeader(int leaderScoreIdx, int l, int r, int sign) {
        // For score indices i in [l..r], their gap changes by sign * totalCnt[i] at value score[i]-score[leaderScoreIdx]
        for (int i = l; i <= r; i++) {
            if (totalCnt[i] == 0) continue;
            int gap = uniqScores[i] - uniqScores[leaderScoreIdx];
            addGapCount(gap, sign * (long) totalCnt[i]);
        }
    }

    static void activateLeaderScore(int sIdx) {
        Integer prev = activeLeaderScores.lower(sIdx);
        Integer next = activeLeaderScores.higher(sIdx);

        // old interval prev covers [sIdx .. next-1] if prev exists
        // new: prev covers [oldL .. sIdx-1], sIdx covers [sIdx .. next-1]
        if (prev != null) {
            int oldL = sIdx;
            int oldR = (next == null ? M - 1 : next - 1);
            if (oldL <= oldR) rangeAssignLeader(prev, oldL, oldR, -1);
        }
        int newL = sIdx;
        int newR = (next == null ? M - 1 : next - 1);
        if (newL <= newR) rangeAssignLeader(sIdx, newL, newR, +1);

        activeLeaderScores.add(sIdx);
    }

    static void deactivateLeaderScore(int sIdx) {
        Integer prev = activeLeaderScores.lower(sIdx);
        Integer next = activeLeaderScores.higher(sIdx);

        // remove interval of sIdx: [sIdx .. next-1]
        int oldL = sIdx;
        int oldR = (next == null ? M - 1 : next - 1);
        if (oldL <= oldR) rangeAssignLeader(sIdx, oldL, oldR, -1);

        // restore prev interval over [sIdx .. next-1] if prev exists
        if (prev != null) {
            int newL = sIdx;
            int newR = (next == null ? M - 1 : next - 1);
            if (newL <= newR) rangeAssignLeader(prev, newL, newR, +1);
        }

        activeLeaderScores.remove(sIdx);
    }

    static long answerQuery(int x) {
        if (activeLeaderScores.isEmpty()) {
            return (x >= N) ? 0 : -1;
        }
        int firstLeader = activeLeaderScores.first();
        long impossible = 0;
        for (int i = 0; i < firstLeader; i++) impossible += totalCnt[i];

        if (impossible > x) return -1;

        long canIgnoreFinite = x - impossible; // uncovered allowed among finite-gap students
        long needCovered = finiteTotal - canIgnoreFinite;
        if (needCovered <= 0) return 0;

        int idx = fw.lowerBound(needCovered);
        return diffValues[idx];
    }

