        M = 0;
        for (int v : all) {
            if (M == 0 || tmp[M - 1] != v) tmp[M++] = v;
        }
        uniqScores = Arrays.copyOf(tmp, M);

        studentScoreIdx = new int[N];
        totalCnt = new int[M];
        for (int i = 0; i < N; i++) {
            int idx = Arrays.binarySearch(uniqScores, score[i]);
            studentScoreIdx[i] = idx;
            totalCnt[idx]++;
        }

        // possible gaps are differences uniqScores[j]-uniqScores[i] for i<=j that actually may appear.
        // Simpler: collect all uniqScores[j]-uniqScores[i] for all score values -> O(M^2), may be too big.
        // But actual gaps used are always differences between two existing score values.
        // Since toggle-update needs arbitrary such differences, we compress all pairwise differences.
        // This assumes M is moderate.
        ArrayList<Integer> diffs = new ArrayList<>();
        diffs.add(0);
        for (int i = 0; i < M; i++) {
            for (int j = i; j < M; j++) {
                diffs.add(uniqScores[j] - uniqScores[i]);
            }
        }
        Collections.sort(diffs);
        int K = 0;
        int[] dtmp = new int[diffs.size()];
        for (int v : diffs) {
            if (K == 0 || dtmp[K - 1] != v) dtmp[K++] = v;
        }
        diffValues = Arrays.copyOf(dtmp, K);
        for (int i = 0; i < K; i++) diffToIdx.put(diffValues[i], i);
        fw = new Fenwick(K + 2);

        leaderCntByScore = new int[M];
        isLeaderStudent = new boolean[N];

        StringBuilder out = new StringBuilder();

        for (int qi = 0; qi < Q; qi++) {
            int type = fs.nextInt();
            if (type == 1) {
                int idx = fs.nextInt() - 1;
                if (!isLeaderStudent[idx]) {
                    isLeaderStudent[idx] = true;
                    int sIdx = studentScoreIdx[idx];
                    if (leaderCntByScore[sIdx] == 0) activateLeaderScore(sIdx);
                    leaderCntByScore[sIdx]++;
                }
            } else if (type == 2) {
                int idx = fs.nextInt() - 1;
                if (isLeaderStudent[idx]) {
                    isLeaderStudent[idx] = false;
                    int sIdx = studentScoreIdx[idx];
                    leaderCntByScore[sIdx]--;
                    if (leaderCntByScore[sIdx] == 0) deactivateLeaderScore(sIdx);
                }
            } else {
                int x = fs.nextInt();
                out.append(answerQuery(x)).append('\n');
            }
        }

        System.out.print(out.toString());
    }
}

