#include <bits/stdc++.h>
using namespace std;

using ll = long long;

struct SegTree {
    int n;
    vector<int> seg;
    SegTree() {}
    SegTree(int sz) { init(sz); }

    void init(int sz) {
        n = 1;
        while (n < sz) n <<= 1;
        seg.assign(2 * n, -1);
    }

    void update(int pos, int val) {
        pos += n;
        seg[pos] = val;
        for (pos >>= 1; pos; pos >>= 1) {
            seg[pos] = max(seg[pos << 1], seg[pos << 1 | 1]);
        }
    }

    int queryMax(int l, int r) { // inclusive
        if (l > r) return -1;
        l += n; r += n;
        int res = -1;
        while (l <= r) {
            if (l & 1) res = max(res, seg[l++]);
            if (!(r & 1)) res = max(res, seg[r--]);
            l >>= 1; r >>= 1;
        }
        return res;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, Q;
    cin >> N >> Q;
    vector<ll> a(N);
    for (int i = 0; i < N; ++i) cin >> a[i];

    vector<pair<char,int>> ops(Q);
    vector<ll> askX;
    vector<ll> vals = a;

    for (int i = 0; i < Q; ++i) {
        char c;
        int v;
        cin >> c >> v;
        ops[i] = {c, v};
        if (c == '?') askX.push_back(v);
    }

    sort(vals.begin(), vals.end());
    vals.erase(unique(vals.begin(), vals.end()), vals.end());

    int M = (int)vals.size();
    vector<vector<int>> posByScore(M);
    for (int i = 0; i < N; ++i) {
        int id = lower_bound(vals.begin(), vals.end(), a[i]) - vals.begin();
        posByScore[id].push_back(i);
    }

    vector<int> scoreId(N);
    for (int i = 0; i < N; ++i) {
        scoreId[i] = lower_bound(vals.begin(), vals.end(), a[i]) - vals.begin();
    }

    vector<int> isLeader(N, 0);
    vector< set<int> > leadersAtScore(M);
    SegTree st(M);

    auto refreshScore = [&](int sid) {
        if (leadersAtScore[sid].empty()) st.update(sid, -1);
        else st.update(sid, *leadersAtScore[sid].rbegin());
    };

    auto count_uncovered = [&](ll r)->int {
        int covered = 0;
        for (int sid = 0; sid < M; ++sid) {
            ll s = vals[sid];
            ll low = s - r;
            int lid = lower_bound(vals.begin(), vals.end(), low) - vals.begin();
            int bestLeaderPos = st.queryMax(lid, sid);
            if (bestLeaderPos == -1) continue;

            const auto &vec = posByScore[sid];
            covered += upper_bound(vec.begin(), vec.end(), bestLeaderPos) - vec.begin();
        }
        return N - covered;
    };

    for (auto [c, v] : ops) {
        if (c == '+') {
            --v;
            if (!isLeader[v]) {
                isLeader[v] = 1;
                leadersAtScore[scoreId[v]].insert(v);
                refreshScore(scoreId[v]);
            }
        } else if (c == '-') {
            --v;
            if (isLeader[v]) {
                isLeader[v] = 0;
                leadersAtScore[scoreId[v]].erase(v);
                refreshScore(scoreId[v]);
            }
        } else {
            int x = v;
            ll lo = -1, hi = (ll)4e18;
            while (hi - lo > 1) {
                ll mid = lo + (hi - lo) / 2;
                if (count_uncovered(mid) <= x) hi = mid;
                else lo = mid;
            }
            cout << hi << '\n';
        }
    }

    return 0;
}

